INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-v7-hunter-original', 1, 'NG-H155 Howitzer Rail Gun (1)', '1D6x10 M.D. per 40 round burst; 2D6x10 M.D. per double burst at one target', 1, '6,000 ft (1,828 m)', 'Each single shot or burst counts as one melee action/attack', 'Two 80,000 round drums, 2,000 bursts or 1,000 double bursts each; the second feeds when the first runs dry. A drum reload runs about two minutes with the right gear and training, 1D6x10 minutes for anyone but a robot or weapons specialist', NULL, 'Anti-armor and assault, secondarily anti-aircraft and anti-missile. A rapid-fire, self-loading gun in a turret that turns 360 degrees with a 90 degree arc up and down, fired by any crew member or the gunner. It leaves a 20 ft (6 m) blind spot at the robot''s feet and a 30 ft (9 m) one straight overhead.'),
  ('ng-v7-hunter-original', 2, 'Forearm Rocket Launchers (6 total; 3 per arm)', 'By missile; fragmentation (5D6 M.D.) or plasma (1D6x10 M.D.) as a rule', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3, 4 or 6', '18, nine per arm', NULL, 'Anti-armor and anti-aircraft, secondarily anti-personnel and defense. Low-profile recessed mini-missile tubes; point and shoot.'),
  ('ng-v7-hunter-original', 3, 'NG-330 Heavy Laser (1, Crotch Gun)', '5D6 M.D. per blast', 1, '2,000 ft (610 m)', 'Each single blast counts as one melee action/attack', 'Effectively unlimited', NULL, 'Anti-personnel, secondarily defense. A single-barreled laser on the lower abdomen that clears infantry from around the feet and the main gun''s blind spot; its turret swings 180 degrees down, forward and back.'),
  ('ng-v7-hunter-block-iv', 1, '(Option A) NG-H155 Howitzer Rail Gun', '1D6x10 M.D. per 40 round burst; 2D6x10 M.D. per double burst at one target', 1, '6,000 ft (1,828 m)', 'Each single blast or burst counts as one melee action/attack', 'Two 80,000 round drums, 2,000 bursts or 1,000 double bursts each; the second feeds when the first runs dry; a fully automated drum reload takes about two minutes', NULL, 'Assault and anti-armor, secondarily anti-aircraft. The standard gun in the head turret, which gives a full 360 degree field of fire; the turret''s sensor drum and the chest sensor array remove the older blocks'' blind spots. Can load the Gunwolf''s anti-supernatural rail gun rounds.'),
  ('ng-v7-hunter-block-iv', 2, '(Option B) NG-505 Heavy Rail Cannon', '2D4x10 M.D. per shell', 1, '4,000 ft (1,219 m)', 'Each shot counts as one melee attack', '600 shells in two oversized 505 drums', NULL, 'Assault and anti-armor, secondarily anti-fortification. Printed here as the NG-R505 Rail Cannon and named as the book''s gear row (p.211), whose own entry prints 1D6x10+3 M.D.; the figures stored here are this page''s. Replaces the Howitzer: steadier single-shell damage at shorter range.'),
  ('ng-v7-hunter-block-iv', 3, '(Option C) NG-515IC Ion Cannon', '6D6+4 M.D. per blast', 1, '4,000 ft (1,219 m)', 'Single shot only', 'Effectively unlimited', NULL, 'Anti-armor and assault, secondarily anti-personnel and anti-fortification. Replaces the Howitzer with heavy energy blasts at shorter range.'),
  ('ng-v7-hunter-block-iv', 4, 'Forearm Mini-Missile Launchers (2)', 'By missile; fragmentation (5D6 M.D.) or plasma (1D6x10 M.D.) as a rule', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3, 4 or 6', '24, 12 per arm', NULL, 'Anti-armor and anti-missile, secondarily anti-personnel and defense. Hidden low-profile launchers in the armored forearms, unchanged through Blocks I-IV, which make a nasty surprise at range or in a brawl.'),
  ('ng-v7-hunter-block-iv', 5, '(Option A) NG-333 Heavy Laser Belly Gun (1)', '5D6+3 M.D. per triple blast, the three fired together', 1, '2,000 ft (610 m)', 'Each triple blast counts as one melee attack', 'Effectively unlimited', NULL, 'Anti-personnel and assault, secondarily defense. The so-called crotch-cannon between the legs, for infantry exploiting the old blind spots. Whichever belly option is fitted, its turret swings 180 degrees down, forward and back, firing straight ahead.'),
  ('ng-v7-hunter-block-iv', 6, '(Option B) Heavy Flamethrower (1)', '1D4x10 M.D. to the target and all within 10 ft (3 m); 3D6 M.D. on diesel or gasoline', 1, '400 ft (122 m)', 'Each burst counts as one melee action/attack', '48 bursts from an 80 gallon (302 liter) reserve; refuel with military napalm, or diesel or gasoline at reduced damage', NULL, 'Anti-structure and defense, secondarily anti-personnel and assault. Replaces the belly laser, for swarms of small monsters and troops at its feet, for clearing bunkers and for creatures that fear fire. Valves seal it under water.'),
  ('ng-v7-hunter-block-iv', 7, '(Option C) Medium NG-223 Chest Rail Gun (1)', '5D6 M.D. per 60 round burst, +4 M.D. within 10 ft (3 m); 1-2 M.D. per round', 1, '2,000 ft (610 m) conventional and silver-coated rounds; 1,000 ft (305 m) weighted wood rounds with silver rings', 'Each single shot or burst counts as one melee attack', '6,000 rounds, 100 bursts', NULL, 'Assault and anti-personnel, secondarily defense. Replaces the belly laser for ground targets and foes in a grapple; fires conventional, silver-coated or wood-and-silver rounds as the Gunwolf''s does.'),
  ('ng-v7-hunter-block-iv', 8, 'NG-133 Light Laser Chest Gun', '2D6 M.D. per blast', 1, '2,000 ft (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Anti-personnel and assault, secondarily defense. New on the Block IV: a small turret guarding the chest sensor pod and driving off troops who come too close; 90 degrees up and down and a 45 degree side-to-side sweep. Printed as 2D6 per blast without a unit.'),
  ('ng-mmb01-big-papa', 1, 'NG-A48 Mini-Missile Launcher', 'By missile type; standard issue is fragmentation (5D6 M.D.)', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3 or 4; a single missile or a volley counts as one melee attack', '48, with another 48 usually stowed in the cargo hold; reloading takes a trained crewman 1D4+1 minutes, six more for the untrained', NULL, 'Defense. A box launcher in the nose under the cockpit, turning 90 degrees left or right and 45 degrees up or down.'),
  ('ng-mmb01-big-papa', 2, 'Large Pry Bar/Jaws of Life Apparatus (1 pair per hand)', '3D6+6 M.D. spreading openings, prying hatches or ripping through hulls and debris; not for punches', 1, 'Touch/close combat', NULL, 'Effectively unlimited', NULL, 'Rescue and forced entry, secondarily anti-fortification. Weapon 2a. Two tong-like bars, held together when idle so they look like one; driven into a seam and spread to force doors and widen holes. Robotic pry/tear strength 50, yet gentle enough to lift the injured.'),
  ('ng-mmb01-big-papa', 3, 'M.D. Chainsaw (1 per hand)', '5D6 M.D. per attack; 1D4 M.D. plus Robot P.S. punch damage as a blade when switched off', 1, 'Touch/close combat', NULL, 'Effectively unlimited', NULL, 'Rescue and cutting through wreckage, secondarily anti-fortification, sabotage and defense. Weapon 2b. A 5 ft (1.5 m) blade that folds back into a forearm housing; two melee actions to deploy or stow. A modular swap for a silver-toothed saw serves against the supernatural, but the silver wears off after 2D4 uses on M.D.C. armor.'),
  ('ng-mmb01-big-papa', 4, 'Laser Torch (1 per hand)', 'Settings: 3D6, 5D6 or 1D6x10 S.D.C.; 1, 1D4 or 2D4 M.D.', 1, '40 ft (12.2 m)', 'Each blast counts as one melee attack/action', 'Effectively unlimited', NULL, 'Cutting and rescue, secondarily defense. Weapon 2c. A folding finger that cuts precisely through debris; point and fire.'),
  ('ng-mmb01-big-papa', 5, 'Laser Scalpel (1 per hand)', 'Settings: 1, 1D4, 2D4 or 4D4 S.D.C.', 0, '12 ft (3.6 m)', 'Each blast counts as one melee attack/action', 'Effectively unlimited', NULL, 'Cutting and rescue, secondarily defense. Weapon 2d. A finer laser on the torch finger for soldering, cutting wire, amputation, cauterizing and field surgery; folds back.'),
  ('ng-mmb01-big-papa', 6, 'S.D.C. Cutting Tool (1 per hand)', '1, 1D4 or 2D4 S.D.C.', 0, 'Melee combat', NULL, 'Effectively unlimited', NULL, 'Rescue and cutting. Weapon 2f. A dinner-plate-sized circular blade for cutting off clothing and light S.D.C. material. (Weapon 2e, the Clamp Finger, deals no damage and is in the description.)'),
  ('ng-mmb02-junior', 1, 'NG-A16 Mini-Missile Launcher', 'By missile type; standard issue is fragmentation (5D6 M.D.)', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3 or 4; a single missile or a volley counts as one melee attack', '16, with another 32 usually stowed in the cargo hold; reloading takes a trained crewman 1D4+1 minutes, six more for the untrained', NULL, 'Defense. A box launcher in Junior''s nose under the cockpit, turning 90 degrees left or right and 45 degrees up or down.'),
  ('ng-mmb02-junior', 2, 'Large Pry Bar/Jaws of Life Apparatus (2 per hand)', '2D6+4 M.D. spreading openings, prying hatches or ripping through hulls and debris; not for punches', 1, 'Touch/close combat', NULL, 'Effectively unlimited', NULL, 'Rescue and forced entry, secondarily anti-fortification. Weapon 2a. Big Papa''s tool scaled down: Robotic pry/tear strength 40, still gentle enough to lift the injured.'),
  ('ng-mmb02-junior', 3, 'M.D. Chainsaw (1 per hand)', '2D6+3 M.D. per attack; 1D4 M.D. plus Robot P.S. punch damage as a blade when switched off', 1, 'Touch/close combat', NULL, 'Effectively unlimited', NULL, 'Rescue and cutting through wreckage, secondarily anti-fortification, sabotage and defense. Weapon 2b. A 2 ft (0.6 m) blade folding into a forearm housing; two melee actions to deploy or stow.'),
  ('ng-mmb02-junior', 4, 'Laser Torch (1 per hand)', 'Settings: 1D6, 2D6, 4D6 or 1D4x10 S.D.C.; 1 or 1D4 M.D.', 1, '40 ft (12.2 m)', 'Each blast counts as one melee attack/action', 'Effectively unlimited', NULL, 'Cutting and rescue, secondarily defense. Weapon 2c. Big Papa''s cutting finger, smaller and weaker.'),
  ('ng-mmb02-junior', 5, 'Laser Scalpel (1 per hand)', 'Settings: 1, 1D4, 2D4 or 3D4 S.D.C.', 0, '12 ft (3.6 m)', 'Each blast counts as one melee attack/action', 'Effectively unlimited', NULL, 'Cutting and rescue, secondarily defense. Weapon 2d. For soldering, cutting, amputation, cauterizing and field surgery; folds back.'),
  ('ng-mmb02-junior', 6, 'S.D.C. Cutting Tool (1 per hand)', '1, 1D4 or 1D6 S.D.C.', 0, 'Melee combat', NULL, 'Effectively unlimited', NULL, 'Rescue and cutting. Weapon 2f. A saucer-sized circular blade for clothing and light S.D.C. material. (Weapon 2e, the Clamp Finger, deals no damage and is in the description.)');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 machines are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicles WHERE slug IN ('ng-v7-hunter-original', 'ng-v7-hunter-block-iv', 'ng-mmb01-big-papa', 'ng-mmb02-junior');
SELECT 'their 74 locations are in' AS assertion, count(*) AS got, 74 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-v7-hunter-original', 'ng-v7-hunter-block-iv', 'ng-mmb01-big-papa', 'ng-mmb02-junior');
SELECT 'their 23 weapon entries are in' AS assertion, count(*) AS got, 23 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-v7-hunter-original', 'ng-v7-hunter-block-iv', 'ng-mmb01-big-papa', 'ng-mmb02-junior');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-v7-hunter-original', 'ng-v7-hunter-block-iv', 'ng-mmb01-big-papa', 'ng-mmb02-junior') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

